<script setup lang="ts">
import {computed,nextTick,onMounted,ref,watch} from 'vue'
import {Folder,FolderOpen,FolderPlus,Upload,Download,Search,Grid2X2,List,ChevronRight,ChevronLeft,ArrowUp,RefreshCw,Trash2,RotateCcw,FileText,File,Server,HardDrive,LogOut,X,Info,Pencil,MoveRight,Check,LoaderCircle,ArrowUpDown,ExternalLink,ShieldCheck,PauseCircle} from 'lucide-vue-next'
import {request,setCSRF,endpoint,bytes,upload,type Entry,type User,type Root,type TrashItem} from './client'
const user=ref<User|null>(null),ready=ref(false),loginBusy=ref(false),loginName=ref(''),loginPassword=ref(''),error=ref(''),notice=ref('')
const roots=ref<Root[]>([]),root=ref('personal'),path=ref(''),entries=ref<Entry[]>([]),trashItems=ref<TrashItem[]>([]),trash=ref(false),selected=ref<Entry|null>(null),selectedTrash=ref<TrashItem|null>(null),query=ref(''),loading=ref(false),view=ref(localStorage.getItem('drive.view')||'grid'),hidden=ref(false),details=ref(true)
const history=ref<string[]>([])
const action=ref<'mkdir'|'rename'|'move'|'trash'|'remove'|null>(null),actionName=ref(''),busy=ref(false)
const editor=ref<{entry:Entry;content:string;original:string;etag:string;root:string}|null>(null),editorBusy=ref(false)
const input=ref<HTMLInputElement|null>(null)
type Transfer={id:number;name:string;progress:number;status:string;error:string;root:string;path:string;file:File;xhr?:XMLHttpRequest}
const transfers=ref<Transfer[]>([]),showTransfers=ref(false)
let loadRevision=0
const display=computed(()=>entries.value.filter(e=>(hidden.value||!e.name.startsWith('.'))&&e.name.toLocaleLowerCase('vi').includes(query.value.toLocaleLowerCase('vi'))))
const rootName=computed(()=>roots.value.find(r=>r.id===root.value)?.name||'Tệp của tôi')
const crumbs=computed(()=>path.value.split('/').filter(Boolean))
const selectedItem=computed(()=>trash.value?selectedTrash.value:selected.value)
const dirty=computed(()=>!!editor.value&&editor.value.content!==editor.value.original)
const modalOpen=computed(()=>!!action.value||!!editor.value)
let priorFocus:HTMLElement|null=null
watch(modalOpen,async value=>{if(value)priorFocus=document.activeElement as HTMLElement|null;await nextTick();if(value)document.querySelector<HTMLElement>('[aria-modal="true"] input, [aria-modal="true"] textarea, [aria-modal="true"] button')?.focus();else if(priorFocus?.isConnected)priorFocus.focus()})
globalThis.addEventListener('keydown',e=>{if(!modalOpen.value)return;if(e.key==='Escape'&&!busy.value&&!editorBusy.value){if(editor.value)closeEditor();else action.value=null}if(e.key==='Tab'){const nodes=[...document.querySelectorAll<HTMLElement>('[aria-modal="true"] button, [aria-modal="true"] input, [aria-modal="true"] textarea')].filter(el=>!el.hasAttribute('disabled')&&el.getClientRects().length);const first=nodes[0],last=nodes.at(-1);if(first&&(e.shiftKey?document.activeElement===first:document.activeElement===last)){e.preventDefault();(e.shiftKey?last:first)?.focus()}}})
const activeTransfers=computed(()=>transfers.value.filter(t=>t.status==='uploading').length)
function notify(message:string){notice.value=message;setTimeout(()=>notice.value='',6000)}
async function init(){const session=await request<{user:User;csrfToken:string}>('/session');user.value=session.user;setCSRF(session.csrfToken);roots.value=(await request<{roots:Root[]}>('/roots')).roots;await load()}
async function login(){loginBusy.value=true;error.value='';try{const session=await request<{user:User;csrfToken:string}>('/login',{method:'POST',body:JSON.stringify({username:loginName.value,password:loginPassword.value})});loginPassword.value='';user.value=session.user;setCSRF(session.csrfToken);roots.value=(await request<{roots:Root[]}>('/roots')).roots;await load()}catch(e){error.value=message(e)}finally{loginBusy.value=false}}
async function logout(){if(activeTransfers.value&&!confirm('Đăng xuất sẽ hủy các lần tải lên đang chạy. Tiếp tục?'))return;if(dirty.value&&!confirm('Bỏ thay đổi văn bản chưa lưu và đăng xuất?'))return;try{await request('/logout',{method:'POST',body:'{}'});transfers.value.forEach(t=>t.xhr?.abort());transfers.value=[];editor.value=null;user.value=null;entries.value=[];selected.value=null;selectedTrash.value=null;root.value='personal';path.value='';trash.value=false;setCSRF('')}catch(e){error.value=message(e)}}
function message(e:unknown){return e instanceof Error?e.message:'Không hoàn thành yêu cầu.'}
async function load(){const revision=++loadRevision;loading.value=true;error.value='';selected.value=null;selectedTrash.value=null;try{if(trash.value){const result=await request<TrashItem[]>(endpoint('trash',root.value,''));if(revision===loadRevision)trashItems.value=result}else{const result=await request<{entries:Entry[]}>(endpoint('list',root.value,path.value));if(revision===loadRevision)entries.value=result.entries}}catch(e){if(revision===loadRevision){entries.value=[];trashItems.value=[];error.value=message(e)}}finally{if(revision===loadRevision)loading.value=false}}
function navigate(next:string){history.value.push(path.value);path.value=next;query.value='';void load()}
function switchRoot(id:string){root.value=id;path.value='';trash.value=false;history.value=[];query.value='';void load()}
function openTrash(){root.value='personal';path.value='';trash.value=true;query.value='';void load()}
function choose(entry:Entry){selected.value=entry}
function open(entry:Entry){if(entry.kind==='folder')navigate(entry.path);else if(entry.kind==='file')void openText(entry);else notify('Bản đầu không mở symlink hoặc tệp đặc biệt.')}
function setView(value:string){view.value=value;localStorage.setItem('drive.view',value)}
function begin(value:NonNullable<typeof action.value>){if(value!=='mkdir'&&!selected.value)return;action.value=value;actionName.value=value==='rename'?selected.value!.name:value==='move'?selected.value!.path:''}
async function submitAction(){if(!action.value)return;busy.value=true;error.value='';try{const target=action.value==='mkdir'?path.value:selected.value!.path;await request(endpoint(action.value,root.value,target),{method:'POST',body:JSON.stringify(action.value==='move'?{destination:actionName.value}:action.value==='remove'?{confirm:true}:{name:actionName.value})});action.value=null;notify('Đã hoàn thành thao tác.');await load()}catch(e){error.value=message(e)}finally{busy.value=false}}
async function restore(){if(!selectedTrash.value)return;try{await request(endpoint('restore','personal',''),{method:'POST',body:JSON.stringify({id:selectedTrash.value.id})});notify('Đã khôi phục về vị trí ban đầu.');await load()}catch(e){error.value=message(e)}}
async function openText(entry:Entry){if(dirty.value&&!confirm('Bỏ văn bản chưa lưu để mở tệp khác?'))return;editorBusy.value=true;error.value='';try{const result=await request<{content:string;etag:string}>(endpoint('text',root.value,entry.path));editor.value={entry,content:result.content,original:result.content,etag:result.etag,root:root.value}}catch(e){error.value=message(e)}finally{editorBusy.value=false}}
function closeEditor(){if(dirty.value&&!confirm('Bỏ các thay đổi chưa lưu?'))return;editor.value=null}
async function saveText(){if(!editor.value||editorBusy.value)return;const state=editor.value;if(state.root==='system'&&!confirm(`Ghi thay đổi vào /${state.entry.path}? Một bản sao lưu sẽ được tạo cạnh tệp.`))return;editorBusy.value=true;try{const result=await request<{backup:string}>(endpoint('save-text',state.root,state.entry.path),{method:'POST',body:JSON.stringify({content:state.content,etag:state.etag})});state.original=state.content;const fresh=await request<{etag:string}>(endpoint('text',state.root,state.entry.path));state.etag=fresh.etag;notify('Đã lưu. Bản sao: '+result.backup);await load()}catch(e){error.value=message(e)}finally{editorBusy.value=false}}
function download(){if(selected.value)location.href=`/api${endpoint('download',root.value,selected.value.path)}`}
async function startTransfer(t:Transfer){t.status='uploading';t.error='';t.progress=0;try{const handle=upload(t.root,t.path,t.file,p=>t.progress=p);t.xhr=handle.xhr;await handle.done;t.status='done';t.xhr=undefined;if(root.value===t.root&&path.value===t.path&&!trash.value)await load()}catch(e){t.status='error';t.error=message(e);t.xhr=undefined}}
async function queue(files:FileList|File[]|null){if(!files||trash.value)return;const targetRoot=root.value,targetPath=path.value;showTransfers.value=true;for(const file of Array.from(files)){if(!user.value)break;if(file.size>128*1024*1024){error.value=`${file.name}: vượt giới hạn 128 MB.`;continue}const id=Date.now()+Math.random();transfers.value.push({id,name:file.name,progress:0,status:'queued',error:'',root:targetRoot,path:targetPath,file});const t=transfers.value.find(t=>t.id===id)!;await startTransfer(t)}if(input.value)input.value.value=''}
function drop(event:DragEvent){event.preventDefault();void queue(event.dataTransfer?.files||null)}
onMounted(async()=>{try{await init()}catch(e){if(!message(e).includes('đăng nhập'))error.value=message(e)}finally{ready.value=true}})
globalThis.addEventListener('beforeunload',e=>{if(activeTransfers.value||dirty.value){e.preventDefault();e.returnValue=''}})
</script>

<template>
 <div class="drive-app">
  <header class="drive-top" :inert="modalOpen"><a href="/" class="drive-brand"><span><FolderOpen :size="21"/></span><strong>MinhAnOS <b>Drive</b></strong></a><span class="drive-preview">File Station · Preview 0.1</span><div v-if="user" class="drive-account"><span class="avatar">{{user.displayName.charAt(0)}}</span><span>{{user.displayName}}</span><button aria-label="Đăng xuất" @click="logout"><LogOut :size="17"/></button></div></header>
  <main v-if="!ready" class="login-wrap"><LoaderCircle class="spinning"/> Đang mở Drive…</main>
  <main v-else-if="!user" class="login-wrap"><section class="drive-login"><span class="login-folder"><FolderOpen :size="36"/></span><div class="eyebrow">KHÔNG GIAN CỦA BẠN</div><h1>Tệp của bạn.<br>Luôn trong tầm tay.</h1><p>Đăng nhập Drive bằng tài khoản MinhAnOS.<br>Ứng dụng hoạt động độc lập với desktop.</p><form @submit.prevent="login"><label>Tên đăng nhập<input v-model="loginName" autocomplete="username" required maxlength="64" autofocus></label><label>Mật khẩu<input v-model="loginPassword" type="password" autocomplete="current-password" required maxlength="256"></label><p v-if="error" role="alert" class="error">{{error}}</p><button class="primary" :disabled="loginBusy">{{loginBusy?'Đang đăng nhập…':'Mở không gian của tôi'}}<ChevronRight :size="17"/></button></form><small><ShieldCheck :size="14"/> Phiên Drive riêng · Tệp tách theo tài khoản</small></section></main>
  <div v-else class="drive-layout" :inert="modalOpen">
   <aside class="drive-sidebar"><span class="nav-label">KHÔNG GIAN LƯU TRỮ</span><button v-for="item in roots" :key="item.id" :class="{active:root===item.id&&!trash}" @click="switchRoot(item.id)"><component :is="item.id==='system'?Server:Folder" :size="19"/>{{item.name}}<span v-if="item.id==='system'" class="admin-label">ADMIN</span></button><button :class="{active:trash}" @click="openTrash"><Trash2 :size="19"/>Thùng rác</button><div class="sidebar-bottom"><HardDrive :size="19"/><strong>Drive độc lập</strong><p>Dữ liệu nằm trên máy chủ.<br>Desktop là lối truy cập tùy chọn.</p><span>Giới hạn tải lên: 128 MB/tệp</span></div></aside>
   <main class="drive-main" @dragover.prevent @drop="drop">
    <div class="drive-heading"><div><span class="eyebrow">{{root==='system'?'QUẢN TRỊ MÁY CHỦ':'KHÔNG GIAN CÁ NHÂN'}}</span><h1>{{trash?'Thùng rác':crumbs.at(-1)||rootName}}</h1><p>{{trash?'Khôi phục tệp về vị trí cũ.':root==='system'?'Tệp thật trên Debian · Thao tác bằng quyền quản trị.':'Một nơi cho tài liệu và những điều bạn đang tạo ra.'}}</p></div><div v-if="!trash" class="heading-actions"><button @click="begin('mkdir')"><FolderPlus :size="17"/>Thư mục mới</button><button class="primary" @click="input?.click()"><Upload :size="17"/>Tải lên</button><input ref="input" type="file" multiple hidden @change="queue(($event.target as HTMLInputElement).files)"></div></div>
    <div class="drive-toolbar"><div class="navigation-actions"><button :disabled="!history.length||trash" aria-label="Quay lại" @click="path=history.pop()||'';load()"><ChevronLeft :size="18"/></button><button :disabled="!path||trash" aria-label="Thư mục cha" @click="navigate(crumbs.slice(0,-1).join('/'))"><ArrowUp :size="17"/></button><button aria-label="Làm mới" :disabled="loading" @click="load"><RefreshCw :size="17" :class="{spinning:loading}"/></button></div><label class="file-search"><Search :size="17"/><input v-model="query" placeholder="Tìm trong thư mục…" aria-label="Tìm trong thư mục"></label><label class="hidden-toggle"><input v-model="hidden" type="checkbox">Tệp ẩn</label><div class="view-toggle"><button :class="{chosen:view==='grid'}" aria-label="Dạng lưới" @click="setView('grid')"><Grid2X2 :size="18"/></button><button :class="{chosen:view==='list'}" aria-label="Dạng danh sách" @click="setView('list')"><List :size="18"/></button><button aria-label="Ẩn hiện thông tin" @click="details=!details"><Info :size="18"/></button></div></div>
    <div class="breadcrumbs"><button @click="trash?openTrash():navigate('')"><component :is="trash?Trash2:root==='system'?Server:Folder" :size="15"/>{{trash?'Thùng rác':rootName}}</button><template v-for="(part,index) in crumbs" :key="index"><ChevronRight :size="12"/><button @click="navigate(crumbs.slice(0,index+1).join('/'))">{{part}}</button></template><span v-if="root==='system'" class="system-path">/{{path}}</span></div>
    <div v-if="error" class="error-banner" role="alert"><Info :size="17"/><span>{{error}}</span><button aria-label="Đóng lỗi" @click="error='' "><X :size="16"/></button></div><div v-if="notice" class="notice" role="status"><Check :size="16"/>{{notice}}</div>
    <div class="files-layout" :class="{'without-details':!details}"><section class="file-browser" aria-label="Danh sách tệp">
     <div v-if="loading" class="empty-files"><LoaderCircle class="spinning" :size="28"/><p>Đang đọc thư mục…</p></div>
     <template v-else-if="trash"><div v-if="!trashItems.length" class="empty-files"><Trash2 :size="40"/><h2>Thùng rác đang trống</h2></div><button v-for="item in trashItems.filter(t=>t.name.toLocaleLowerCase('vi').includes(query.toLocaleLowerCase('vi')))" :key="item.id" class="trash-row" :class="{selected:selectedTrash?.id===item.id}" @click="selectedTrash=item"><File :size="23"/><span><strong>{{item.name}}</strong><small>{{item.path}}</small></span><time>{{new Date(item.deleted).toLocaleDateString('vi')}}</time></button></template>
     <template v-else><div class="browser-label"><span>{{display.length}} MỤC</span><span>{{view==='grid'?'Chạm để chọn · Mở để duyệt':'Tên · Kích thước · Quyền'}}</span></div><div v-if="!display.length" class="empty-files"><FolderOpen :size="47"/><h2>{{error?'Chưa đọc được thư mục':query?'Không tìm thấy tệp':'Không gian đang trống'}}</h2><p v-if="!error">{{query?'Thử tìm bằng tên khác.':'Tạo thư mục hoặc kéo tệp vào đây để bắt đầu.'}}</p></div><div class="file-items" :class="{rows:view==='list'}"><button v-for="entry in display" :key="entry.path" class="file-item" :class="{selected:selected?.path===entry.path,folder:entry.kind==='folder'}" :aria-label="`Chọn ${entry.name}`" @click="choose(entry)" @dblclick="open(entry)" @keydown.enter.prevent="open(entry)"><span class="file-symbol"><component :is="entry.kind==='folder'?Folder:entry.kind==='file'?FileText:Info" :size="45" :stroke-width="1.3"/></span><span class="file-name">{{entry.name}}</span><span class="file-size">{{entry.kind==='folder'?'Thư mục':bytes(entry.size)}}</span><span class="file-mode">{{entry.mode}}</span><span class="file-date">{{new Date(entry.modified).toLocaleDateString('vi')}}</span></button></div></template>
    </section>
    <aside v-if="details" class="file-inspector" aria-label="Thông tin tệp"><div class="inspector-label">Thông tin <Info :size="15"/></div><template v-if="selectedItem"><div class="inspector-preview"><component :is="!trash&&selected?.kind==='folder'?Folder:FileText" :size="54" :stroke-width="1.2"/></div><h2>{{selectedItem.name}}</h2><p class="inspector-path">{{selectedItem.path}}</p><template v-if="!trash&&selected"><dl><div><dt>Loại</dt><dd>{{selected.kind}}</dd></div><div><dt>Kích thước</dt><dd>{{bytes(selected.size)}}</dd></div><div><dt>Quyền Linux</dt><dd>{{selected.mode}}</dd></div><div><dt>UID / GID</dt><dd>{{selected.uid}} / {{selected.gid}}</dd></div><div><dt>Thay đổi</dt><dd>{{new Date(selected.modified).toLocaleString('vi')}}</dd></div></dl><div class="inspector-actions"><button v-if="selected.kind==='folder'" class="primary" @click="open(selected)"><FolderOpen :size="17"/>Mở thư mục</button><template v-if="selected.kind==='file'"><button class="primary" @click="download"><Download :size="16"/>Tải xuống</button><button :disabled="editorBusy" @click="openText(selected)"><FileText :size="16"/>Xem / sửa văn bản</button></template><template v-if="selected.kind==='file'||selected.kind==='folder'"><button @click="begin('rename')"><Pencil :size="16"/>Đổi tên</button><button @click="begin('move')"><MoveRight :size="16"/>Di chuyển</button><button class="danger-text" @click="begin(root==='system'?'remove':'trash')"><Trash2 :size="16"/>{{root==='system'?'Xóa khỏi hệ thống':'Đưa vào thùng rác'}}</button></template></div></template><button v-else class="primary" @click="restore"><RotateCcw :size="16"/>Khôi phục</button></template><div v-else class="inspector-placeholder"><Folder :size="35"/><p>Chọn một tệp hoặc thư mục<br>để xem thông tin và thao tác.</p></div></aside></div>
    <footer class="files-footer"><span>{{root==='system'?'Agent Debian · Không mở tệp thiết bị, filesystem ảo hoặc symlink':'Tệp riêng theo tài khoản · Lưu trữ trên máy chủ'}}</span><button @click="showTransfers=!showTransfers"><ArrowUpDown :size="16"/>Tác vụ <span v-if="activeTransfers">{{activeTransfers}}</span></button></footer>
   </main>
  </div>
  <section v-if="user&&showTransfers" :inert="modalOpen" class="transfer-panel" aria-label="Tác vụ tải lên"><header><strong>Tác vụ tải lên</strong><button aria-label="Thu gọn tác vụ" @click="showTransfers=false"><X :size="17"/></button></header><p v-if="!transfers.length" class="muted">Chưa có tác vụ. Tệp tối đa 128 MB.</p><div v-for="t in transfers" :key="t.id" class="transfer-row"><File :size="22"/><div><strong>{{t.name}}</strong><small>{{t.status==='done'?'Đã tải lên':t.status==='error'?t.error:t.status==='queued'?'Đang chờ':`${t.progress}% · ${t.progress===100?'Đang chờ máy chủ xác nhận':'Đang gửi'}`}}</small><div class="progress"><i :style="{width:t.progress+'%'}"></i></div></div><button v-if="t.status==='uploading'" :aria-label="`Hủy ${t.name}`" @click="t.xhr?.abort()"><X :size="17"/></button><button v-if="t.status==='error'" :aria-label="`Thử lại ${t.name}`" @click="startTransfer(t)"><RotateCcw :size="17"/></button><Check v-if="t.status==='done'" :size="17"/></div><p class="transfer-note">Đổi thư mục không hủy upload. Đóng hoặc tải lại trang sẽ ngắt truyền; bản đầu chưa hỗ trợ resume.</p></section>
  <div v-if="action" class="modal-scrim"><form class="action-dialog" role="dialog" aria-modal="true" :aria-label="{mkdir:'Thư mục mới',rename:'Đổi tên',move:'Di chuyển',trash:'Đưa vào thùng rác',remove:'Xóa tệp hệ thống'}[action]" @submit.prevent="submitAction"><h2>{{{mkdir:'Thư mục mới',rename:'Đổi tên',move:'Di chuyển',trash:'Đưa vào thùng rác?',remove:'Xóa khỏi hệ thống?'}[action]}}</h2><p v-if="action==='trash'||action==='remove'">{{selected?.path}}<br>{{action==='remove'?'Xóa vĩnh viễn tệp hoặc thư mục rỗng trên Debian.':'Bạn có thể khôi phục từ Thùng rác.'}}</p><label v-else>{{action==='move'?'Đường dẫn đích đầy đủ trong không gian hiện tại':'Tên'}}<input v-model="actionName" required maxlength="4096" autofocus></label><p v-if="error" class="error" role="alert">{{error}}</p><footer><button type="button" :disabled="busy" @click="action=null">Hủy</button><button class="primary" :disabled="busy">{{busy?'Đang thực hiện…':'Xác nhận'}}</button></footer></form></div>
  <div v-if="editor" class="modal-scrim"><section class="text-editor" role="dialog" aria-modal="true" aria-label="Trình sửa văn bản"><header><div><FileText :size="20"/><span><strong>{{editor.entry.name}}</strong><small>{{editor.root==='system'?'Hệ thống Debian':'Tệp của tôi'}} / {{editor.entry.path}}</small></span><i v-if="dirty" class="draft-dot"></i></div><button aria-label="Đóng trình sửa" :disabled="editorBusy" @click="closeEditor"><X :size="19"/></button></header><div v-if="error" class="error-banner" role="alert">{{error}}</div><textarea v-model="editor.content" aria-label="Nội dung tệp" spellcheck="false" :disabled="editorBusy"></textarea><footer><span>UTF-8 · Tối đa 256 KB · Tạo bản sao trước khi lưu</span><button class="primary" :disabled="!dirty||editorBusy" @click="saveText">{{editorBusy?'Đang lưu…':'Lưu thay đổi'}}</button></footer></section></div>
 </div>
</template>
